const path = require('path');
require('dotenv').config({ path: path.resolve(__dirname, '..', '.env') });
const mongoose = require('mongoose');

const SCHOOL_ID = new mongoose.Types.ObjectId('69ce960a98ca4ee738d25416');
const CREATED_BY = new mongoose.Types.ObjectId('69ce960b98ca4ee738d25432');

let blockNum = 0;
function bid() { return 'block-' + String(++blockNum).padStart(3, '0'); }

function t(order, content) {
  return { blockId: bid(), type: 'text', order, content, points: 0, hints: [], explanation: '', metadata: {}, curriculumNodeId: null, cognitiveLevel: null };
}
function q(order, question, options, correctIndex, explanation, hints) {
  return {
    blockId: bid(), type: 'quiz', order,
    content: JSON.stringify({ question, options, correctIndex }),
    points: 1, hints: hints || [], explanation: explanation || '',
    metadata: { options, correctIndex }, curriculumNodeId: null, cognitiveLevel: null,
  };
}
function fb(order, text, blanks, explanation, hints) {
  return {
    blockId: bid(), type: 'fill_blank', order,
    content: JSON.stringify({ text, blanks }),
    points: blanks.length, hints: hints || [], explanation: explanation || '',
    metadata: { blanks }, curriculumNodeId: null, cognitiveLevel: null,
  };
}

// =============================================================================
// CHAPTER 1: Basic Concepts and the Economic Problem (Term 1, Weeks 1-3)
// =============================================================================

blockNum = 0;
const ch1_lesson1 = [
  t(1, "## What Is Economics?\n\nEconomics is the social science that studies how individuals, businesses, and governments make choices about allocating scarce resources to satisfy unlimited human wants and needs.\n\n### Branches of Economics\n\n| Branch | Focus | Examples |\n|--------|-------|----------|\n| **Microeconomics** | Individual markets, firms, and consumers | Supply and demand, pricing, market structures |\n| **Macroeconomics** | The economy as a whole | GDP, inflation, unemployment, monetary policy |\n\n### The Setting of Economics\n\nEconomics operates within a specific context:\n- **Households** make decisions about spending, saving, and working\n- **Firms** decide what to produce, how to produce, and what to charge\n- **Government** regulates, taxes, and provides public services\n\nIn South Africa, economics is shaped by the country's history of apartheid, extreme inequality, high unemployment, and the need for transformation. Understanding economics helps us make sense of issues such as load shedding, rising food prices, and the debate around land reform."),
  t(2, "### Needs, Wants, and the Scarcity Problem\n\n**Needs** are things required for survival: food, water, shelter, clothing, healthcare.\n\n**Wants** are things desired but not essential for survival: smartphones, designer clothing, holidays, luxury cars.\n\nThe fundamental economic problem is that **human wants are unlimited** but **resources are scarce** (limited). This means society can never produce everything everyone wants.\n\n**Scarcity** means there are not enough resources to satisfy all human wants. Even wealthy countries face scarcity — they simply have more resources, but still cannot produce unlimited goods.\n\n**Free goods vs economic goods:**\n- **Free goods**: Available in unlimited quantities at no cost (e.g., air, sunlight)\n- **Economic goods**: Scarce goods that require resources to produce (e.g., bread, houses, education)\n\nIn South Africa, scarcity is visible everywhere: not enough houses for everyone (housing backlog of over 2 million), not enough jobs (unemployment above 32%), not enough electricity (load shedding), and not enough clean water in many rural areas."),
  q(3, "Which of the following best describes the basic economic problem?",
    ["Too many resources and not enough wants", "Unlimited wants but limited resources", "Government cannot collect enough taxes", "Businesses make too much profit"], 1,
    "The basic economic problem is that human wants are unlimited, but the resources available to satisfy those wants are scarce (limited). This forces individuals, firms, and governments to make choices."),
  t(4, "### Choice and Opportunity Cost\n\nBecause of scarcity, we must make **choices**. Every choice involves a trade-off — when you choose one thing, you give up the next best alternative.\n\n**Opportunity cost** is the value of the next best alternative that is given up when a choice is made.\n\n**Examples:**\n- A learner chooses to study Economics instead of watching TV. The opportunity cost is the enjoyment of watching TV.\n- Government builds a new hospital instead of a school. The opportunity cost is the school that was not built.\n- A farmer uses land to grow maize instead of sunflowers. The opportunity cost is the sunflower crop.\n\n**Key points about opportunity cost:**\n1. It is always the **next best** alternative, not all alternatives\n2. It applies to individuals, firms, and governments\n3. It is not always measured in money — time, enjoyment, and other benefits count\n4. There is no such thing as a free lunch — everything has an opportunity cost\n\nIn the SA National Budget, the government faces opportunity costs constantly. Spending R100 billion on social grants means R100 billion less for infrastructure, education, or healthcare."),
  fb(5, "The basic economic problem arises because wants are ___ but resources are ___. The value of the next best alternative forgone is called ___ cost.",
    ["unlimited", "scarce", "opportunity"],
    "Scarcity forces choices, and every choice has an opportunity cost. This is the foundation of all economic decision-making."),
  t(6, "### The Production Process\n\nProduction is the process of transforming inputs (factors of production) into outputs (goods and services).\n\n**Factors of production:**\n\n| Factor | Description | Remuneration |\n|--------|-------------|-------------|\n| **Land** | All natural resources (soil, water, minerals, forests, climate) | **Rent** |\n| **Labour** | Human physical and mental effort | **Wages/Salaries** |\n| **Capital** | Man-made resources used in production (machinery, tools, buildings) | **Interest** |\n| **Entrepreneurship** | Combining the other factors, taking risks, innovating | **Profit** |\n\n**Types of goods produced:**\n- **Consumer goods**: Bought by households for final use (food, clothing, cars)\n- **Capital goods**: Used to produce other goods (machines, factories, tools)\n- **Intermediate goods**: Used up in the production of other goods (flour for bread, steel for cars)\n\nSouth Africa is rich in natural resources (gold, platinum, coal, iron ore) but faces challenges with the other factors — high unemployment means labour is underutilised, capital investment is low, and entrepreneurship is constrained by red tape and crime."),
  q(7, "Which factor of production earns profit as its remuneration?",
    ["Land", "Labour", "Capital", "Entrepreneurship"], 3,
    "Entrepreneurship earns profit as the reward for organising the other factors, taking risks, and innovating. Land earns rent, labour earns wages/salaries, and capital earns interest."),
  t(8, "### Economic Activities\n\nEconomic activities can be grouped into categories:\n\n**Production**: Creating goods and services to satisfy wants (farming, manufacturing, banking)\n\n**Consumption**: Using goods and services to satisfy wants (eating food, using electricity, travelling)\n\n**Exchange**: Trading goods and services, usually through the use of money (buying and selling in markets)\n\n**Distribution**: Getting goods from producers to consumers (transport, wholesale, retail)\n\n**Saving**: Setting aside income for future use (bank deposits, retirement funds)\n\n**Investment**: Using saved resources to create new capital goods or financial returns (building a factory, buying shares)\n\n### Decision-Making\n\nEconomics studies how three groups of decision-makers allocate resources:\n1. **Consumers** decide what to buy with their limited income\n2. **Producers** decide what to produce and how to produce it\n3. **Government** decides how to allocate tax revenue and regulate the economy\n\nThese decisions are guided by the three central questions of economics: **What** to produce? **How** to produce? **For whom** to produce?"),
  fb(9, "The three central questions in economics are what to produce, ___ to produce, and for ___ to produce.",
    ["how", "whom"],
    "Every society must answer these three questions. The way they are answered determines the type of economic system (free market, command, or mixed)."),
  q(10, "A farmer has land that can grow either wheat or potatoes. She chooses wheat. The opportunity cost is:",
    ["The cost of seeds and fertiliser for wheat", "The profit she could have made from potatoes", "The total revenue from wheat sales", "The wages she pays her workers"], 1,
    "Opportunity cost is the value of the next best alternative forgone. By choosing wheat, the farmer gives up the profit she could have earned from growing potatoes on the same land."),
];

blockNum = 0;
const ch1_lesson2 = [
  t(1, "## Methods and Relationship with Other Sciences\n\nEconomics uses a systematic approach to study human behaviour in relation to scarce resources.\n\n### Methods of Economics\n\n**Positive economics** deals with facts and objective analysis — what IS:\n- \"South Africa's unemployment rate is 32%\"\n- \"Inflation rose by 5.4% in the last quarter\"\n- These statements can be tested and verified with data\n\n**Normative economics** deals with value judgements — what SHOULD BE:\n- \"The government should increase social grants\"\n- \"Minimum wages should be higher\"\n- These statements involve opinions and cannot be proven true or false\n\n**Scientific method in economics:**\n1. Observe the economic world\n2. Formulate a hypothesis (a testable statement)\n3. Collect data to test the hypothesis\n4. Analyse results and draw conclusions\n5. Develop theories and models\n\n**Ceteris paribus** is a Latin phrase meaning \"all other things being equal.\" Economists use it to isolate the effect of one variable while holding all others constant. For example, the law of demand assumes ceteris paribus — only price changes while income, tastes, and other factors remain the same."),
  t(2, "### Relationship with Other Sciences\n\nEconomics does not exist in isolation. It is connected to many other disciplines:\n\n| Science | Relationship |\n|---------|-------------|\n| **History** | Economic events are shaped by history (apartheid shaped SA's economy; the Great Depression shaped global policy) |\n| **Geography** | Location of resources, climate, and trade routes affect economic activity |\n| **Mathematics/Statistics** | Used for calculations, data analysis, modelling (GDP calculations, inflation indices) |\n| **Political Science** | Government policy decisions affect the economy (fiscal policy, trade agreements) |\n| **Sociology** | Social factors influence economic behaviour (culture, family structure, inequality) |\n| **Psychology** | Understanding consumer behaviour, decision-making, and biases |\n| **Law** | Legal frameworks regulate economic activity (company law, labour law, competition law) |\n| **Environmental Science** | Economic activity affects the environment; sustainability is an economic concern |\n\nIn South Africa, the relationship between economics and politics is especially important. Policies like BBBEE, land reform, and the National Development Plan (NDP) are both political and economic decisions."),
  q(3, "\"The government should raise the minimum wage to R30 per hour\" is an example of:",
    ["Positive economics", "Normative economics", "Microeconomics", "A scientific law"], 1,
    "This is normative economics because it involves a value judgement (what 'should' be done). Positive economics would state facts, such as 'The current minimum wage is R27.58 per hour.'"),
  t(4, "### Goods and Services in More Detail\n\n**Classification of goods:**\n\n**By durability:**\n- **Durable goods**: Last a long time (cars, furniture, appliances)\n- **Semi-durable goods**: Last a moderate period (clothing, shoes, school bags)\n- **Non-durable goods**: Used up quickly or once (food, fuel, toiletries, medicine)\n- **Services**: Intangible — cannot be touched (education, healthcare, haircuts, banking, transport)\n\n**By relationship:**\n- **Substitutes**: Goods that can replace each other (Coca-Cola and Pepsi; butter and margarine)\n- **Complements**: Goods used together (bread and butter; cars and petrol; printers and ink)\n- **Independent goods**: Goods with no relationship (shoes and bread)\n\n**By access:**\n- **Private goods**: Excludable and rival (clothing, food — if you eat it, others cannot)\n- **Public goods**: Non-excludable and non-rival (street lights, national defence, public parks)\n- **Merit goods**: Beneficial to society but underprovided by the market (education, healthcare, libraries)\n- **Demerit goods**: Harmful to society but overconsumed (cigarettes, alcohol, drugs)"),
  fb(5, "Goods that can replace each other are called ___. Goods that are used together are called ___.",
    ["substitutes", "complements"],
    "Coca-Cola and Pepsi are substitutes — you choose one or the other. Cars and petrol are complements — you need both to travel by car."),
  t(6, "### The Economic Problem at Different Levels\n\n**Individual level:**\n- A learner has R50 for lunch. She can buy a pie and a juice, or a burger. She cannot afford both — she must choose.\n- Opportunity cost: the meal she does not buy.\n\n**Business level:**\n- A factory has limited funds. It can buy a new machine or hire more workers, but not both.\n- Opportunity cost: the option not chosen.\n\n**Government level:**\n- Government has a fixed budget. It can build hospitals or schools, but not enough of both.\n- The SA government allocates approximately 20% of the budget to education, making it the largest single expenditure. The opportunity cost is spending on other priorities.\n\n**National level:**\n- A country must decide how to use its resources: produce consumer goods (for immediate consumption) or capital goods (for future growth).\n- Countries that invest heavily in capital goods today (like China did) sacrifice current consumption but enjoy higher growth in the future.\n\n**The trade-off between efficiency and equity:**\n- **Efficiency**: Getting the maximum output from available resources\n- **Equity**: Distributing resources fairly\n- These often conflict — perfectly efficient markets may be very unequal."),
  q(7, "If the SA government increases spending on defence, the opportunity cost might be:",
    ["Higher taxes", "Less spending on education or healthcare", "Higher inflation", "More exports"], 1,
    "With a fixed budget, spending more on defence means less money available for other priorities like education, healthcare, or infrastructure. This is the opportunity cost of the defence spending decision."),
  t(8, "### Rights and Responsibilities\n\nThe South African Constitution guarantees certain economic rights:\n\n**Section 22**: Freedom of trade, occupation, and profession\n**Section 25**: Property rights (including land reform provisions)\n**Section 26**: Right to adequate housing\n**Section 27**: Right to healthcare, food, water, and social security\n**Section 29**: Right to education\n\nThese rights create responsibilities for both citizens and government:\n\n**Citizens' responsibilities:**\n- Pay taxes honestly\n- Use resources responsibly\n- Contribute to the economy through work and enterprise\n- Respect others' property rights\n\n**Government's responsibilities:**\n- Provide basic services (water, electricity, sanitation)\n- Create conditions for economic growth and job creation\n- Protect consumer rights\n- Manage the economy prudently (fiscal and monetary policy)\n- Redistribute resources to reduce inequality\n\nThe promotion or violation of these rights has economic consequences. For example, corruption in government (a violation of responsibility) reduces the resources available for service delivery, harming economic development."),
  fb(9, "Section ___ of the SA Constitution guarantees the right to education. Positive economics deals with ___, while normative economics deals with value judgements.",
    ["29", "facts"],
    "The Constitution provides the legal framework for economic rights. Distinguishing between positive and normative statements is essential for critical thinking in economics."),
  q(10, "Which of the following is an example of a public good?",
    ["A loaf of bread", "A pair of shoes", "National defence", "A cinema ticket"], 2,
    "National defence is non-excludable (everyone benefits whether they pay or not) and non-rival (one person's benefit does not reduce another's). Private goods like bread and shoes are excludable and rival."),
];

